const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2023 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n  font-size: inherit;\n}\n\n*:focus,\n*:focus-visible {\n  outline: none;\n}\n\n:host {\n  overflow-x: auto;\n}\n\n:host,\ndevtools-recording-view,\ndevtools-create-recording-view {\n  display: flex;\n  flex-direction: column;\n  flex: 1;\n  min-height: 0;\n}\n\n.wrapper {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n.header {\n  background-color: var(--sys-color-cdt-base-container);\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  border-bottom: 1px solid var(--sys-color-divider);\n  padding: 0 5px;\n  min-height: 29px;\n  max-height: 29px;\n  gap: 3px;\n}\n\n.separator {\n  background-color: var(--sys-color-divider);\n  width: 1px;\n  height: 17px;\n  margin: 0;\n}\n\nselect {\n  border-radius: 2px;\n  border: 1px solid transparent;\n  height: 24px;\n  max-width: 180px;\n  min-width: 140px;\n  padding: 0 5px;\n  position: relative;\n  color: var(--sys-color-on-surface);\n  background-color: var(--sys-color-cdt-base-container);\n  text-overflow: ellipsis;\n}\n\nselect:disabled {\n  color: var(--sys-color-state-disabled);\n}\n\nselect:not([disabled]):hover,\nselect:not([disabled]):focus-visible,\nselect:not([disabled]):active {\n  background-color: var(--sys-color-state-hover-on-subtle);\n}\n\nselect:not([disabled]):focus-visible {\n  box-shadow: 0 0 0 2px var(--sys-color-state-focus-ring);\n}\n\nselect option {\n  background-color: var(--sys-color-cdt-base-container);\n  color: var(--sys-color-on-surface);\n}\n\ndevtools-menu {\n  width: 0;\n  height: 0;\n  position: absolute;\n}\n\ndevtools-recording-list-view {\n  overflow: auto;\n}\n\n.error {\n  color: var(--sys-color-error);\n  border: 1px solid var(--sys-color-error);\n  background-color: var(--sys-color-error-container);\n  padding: 4px;\n}\n\n.feedback {\n  margin-left: auto;\n  margin-right: 4px;\n}\n\n.feedback .x-link {\n  letter-spacing: 0.03em;\n  text-decoration-line: underline;\n  font-size: 9px;\n  line-height: 16px;\n  color: var(--sys-color-on-surface-subtle);\n  outline-offset: 3px;\n}\n\n.feedback .x-link:focus-visible {\n  outline: -webkit-focus-ring-color auto 1px;\n}\n\n.continue-button {\n  border: none;\n  background-color: transparent;\n  width: 24px;\n  height: 24px;\n  border-radius: 2px;\n}\n\n.continue-button devtools-icon {\n  width: 24px;\n  height: 24px;\n\n  --icon-color: var(--sys-color-primary);\n}\n\n.continue-button:hover,\n.continue-button:focus-visible {\n  background-color: var(--sys-color-state-hover-on-subtle);\n}\n\n.continue-button:disabled {\n  background: var(--sys-color-cdt-base-container);\n  color: var(--sys-color-state-disabled);\n  cursor: not-allowed;\n}\n\n.continue-button:disabled devtools-icon {\n  --icon-color: var(--icon-disabled);\n}\n\ndevtools-shortcut-dialog {\n  padding-right: 6px;\n}\n\n/*# sourceURL=recorderController.css */\n");export default styles;